    REFERENCES public.reconciliation_batches (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE CASCADE;


ALTER TABLE IF EXISTS public.refunds
    ADD CONSTRAINT refunds_transaction_id_foreign FOREIGN KEY (transaction_id)
    REFERENCES public.transactions (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS refunds_transaction_id_index
    ON public.refunds(transaction_id);


ALTER TABLE IF EXISTS public.settlements
    ADD CONSTRAINT settlements_ledger_transaction_id_foreign FOREIGN KEY (ledger_transaction_id)
    REFERENCES public.ledger_transactions (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE NO ACTION;


ALTER TABLE IF EXISTS public.system_config
    ADD CONSTRAINT system_config_updated_by_foreign FOREIGN KEY (updated_by)
    REFERENCES public.platform_users (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE NO ACTION;


ALTER TABLE IF EXISTS public.webhook_delivery_logs
    ADD CONSTRAINT webhook_delivery_logs_merchant_id_foreign FOREIGN KEY (merchant_id)
    REFERENCES public.merchants (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS webhook_delivery_logs_merchant_id_index
    ON public.webhook_delivery_logs(merchant_id);


ALTER TABLE IF EXISTS public.webhook_delivery_logs
    ADD CONSTRAINT webhook_delivery_logs_webhook_id_foreign FOREIGN KEY (webhook_id)
    REFERENCES public.merchant_webhooks (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS webhook_delivery_logs_webhook_id_index
    ON public.webhook_delivery_logs(webhook_id);

END;